fn lookup(id: Int) -> Option[Int] { … }

fn double(id: Int) -> Result[Int, String] {
    let n = lookup(id)?                    // ✗ `double` returns a `Result`, not an `Option`
    Ok(n * 2)
}

fn double(id: Int) -> Result[Int, String] {
    let n = lookup(id).okOr("missing")?    // ✓ `None` becomes an `Err`
    Ok(n * 2)
}
